import sys
import types

from tqdm.contrib import tenumerate


def test_numpy_special_case_keeps_index_value_shape():
    fake_numpy = types.ModuleType('numpy')

    class ndarray(object):
        pass

    class FakeArray(ndarray):
        def __len__(self):
            return 1

    fake_numpy.ndarray = ndarray
    fake_numpy.ndenumerate = lambda _array: iter([((0,), 'value')])
    previous = sys.modules.get('numpy')
    sys.modules['numpy'] = fake_numpy
    try:
        result = list(tenumerate(
            FakeArray(),
            start=5,
            tqdm_class=lambda iterable, **_kwargs: iterable,
        ))
    finally:
        if previous is None:
            sys.modules.pop('numpy', None)
        else:
            sys.modules['numpy'] = previous
    assert result == [((0,), 'value')]
